INSERT INTO `lms_courses` (`id`, `teacher_id`, `category_id`, `product_id`, `course_code`, `title`, `slug`, `description`, `learning_objectives`, `requirements`, `target_audience`, `image`, `intro_video_url`, `price`, `pass_percentage`, `is_free`, `level`, `status`, `satisfaction_enabled`, `max_students`, `current_students`, `completion_criteria`, `created_at`, `updated_at`) VALUES (4,63,6,14,NULL,'Marine Environmental Awareness','marine-environmental-awareness','\r\n\r\nThis course provides mandatory minimum standards of competence of Marine Environmental Awareness in accordance with the provisions of Sections A-II1, A-III/1, A-III/6 and Table A-II/1, A-III/1, A-III/6 of the STCW┬áCode.\r\n┬á\r\n┬á\r\n\r\n',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2022-04-21 21:20:43','2026-06-12 21:24:24'),(5,63,6,15,NULL,'Leadership and Teamwork','leadership-and-teamwork','\r\nThis course provides mandatory minimum standards of competence the Leadership and Teamwork in accordance with the provisions of Sections A-II/1, A-III/1 and A-III/6 and Table┬á A-II/1, A-III/1 and A- III/6 of the STCW┬áCode.\r\n\r\n',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2022-04-21 21:24:16','2026-06-12 21:24:24'),(8,70,6,42,NULL,'Port Facility Security Officer','port-facility-security-officer','\r\nThis course is intented to provide knowledge to those who may be designated to perform the duties and responsibilities of a Port Facility Security Officer in accordance with the provisions of the Prescriptions 2.1.8 and 11, Part A of the ISPS Code.\r\n┬á\r\n\r\n',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2022-04-21 21:29:33','2026-06-12 21:24:24'),(18,63,6,12,NULL,'Personal Safety and Social Responsibilities','personal-safety-and-social-responsibilities','This course provides mandatory minimum standards of competence in Personal Safety and Social Responsibility in accordance with the provisions of the Section A-VI/1 and Table A-VI/1-4 of the STCWCode.',NULL,NULL,NULL,NULL,NULL,0.00,70,0,'intermediate','published',1,NULL,0,'auto','2022-04-21 21:45:24','2026-06-12 21:24:24'),(140,78,6,16,NULL,'Use of Leadership and Managerial Skills','use-of-leadership-and-managerial-skills','Regulations II/2, III/2 ┬áand Table A-II/2 and A-III/2',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2025-04-05 23:45:58','2026-06-12 21:24:24'),(141,78,6,39,NULL,'Maritime English','maritime-english','Regulations II/2, III/2 ┬áand Table A-II/2 and A-III/2',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2025-04-05 23:46:38','2026-06-12 21:24:24'),(142,63,6,40,NULL,'Ship Security Officer','ship-security-officer','Regulation VI/5, Section A-VI/5 and Table A-VI/5 of the 1978 STCW Convention, as amended; Chapter XI-2 of the 1974 SOLAS Convention, as amended, and Prescriptions 2.1.6 and 12 of Part A of the ISPS Code',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2025-04-05 23:48:37','2026-06-12 21:24:24'),(143,63,6,41,NULL,'Company Security Officer','company-security-officer','Chapter XI-2 of the 1974 SOLAS Convention, as amended; Prescriptions 2.1.7 and 11, Part A of the ISPS Code',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2025-04-05 23:49:30','2026-06-12 21:24:24'),(145,63,6,43,NULL,'Security Awareness Training for Port Facility Personnel with Designated Security Duties','security-awareness-training-for-port-facility-personnel-with-designated-security-duties','Formaci├│n en Sensibilizaci├│n Sobre Protecci├│n para el Personal de la Instalaci├│n Portuaria que Tenga Asignadas Tareas de Protecci├│n',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2025-04-05 23:51:28','2026-06-12 21:24:24'),(146,63,6,44,NULL,'Security Awareness Training for All Port Facility Personnel','security-awareness-training-for-all-port-facility-personnel','Formaci├│n en Sensibilizaci├│n Sobre Protecci├│n para todo el Personal de la Instalaci├│n Portuaria┬á',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2025-04-05 23:55:54','2026-06-12 21:24:24'),(147,63,6,46,NULL,'Training Course for Instructors','training-course-for-instructors','Curso Formación para Instructores',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2025-04-05 23:57:34','2026-06-12 21:24:24'),(148,63,6,10,NULL,'Security Training for Seafarers with Designated Security Duties','security-training-for-seafarers-with-designated-security-duties','Formaci├│n sobre Protecci├│n para la Gente de Mar que Tenga Asignadas Tareas de Protecci├│n',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2025-04-06 00:00:41','2026-06-12 21:24:24'),(151,63,6,9,NULL,'Personal Survival Techniques','personal-survival-techniques','',NULL,NULL,NULL,NULL,NULL,0.00,70,1,'intermediate','published',0,NULL,0,'auto','2025-04-28 15:55:07','2026-06-12 21:24:24'),(152,63,6,11,NULL,'Fire Prevention and Fire Fighting','fire-prevention-and-fire-fightubg','Regulation VI/1 STCW',NULL,NULL,NULL,'',NULL,95.00,70,0,'intermediate','published',0,NULL,0,'auto','2025-04-28 16:27:22','2026-06-15 01:59:18');
