  CONSTRAINT `fk_lms_answers_question` FOREIGN KEY (`question_id`) REFERENCES `lms_questions` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4318 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
